.param W_xmsu2=20 L_xmsu2=1
.param W_xmsu3=10 L_xmsu3=1
.param W_xmsu4=10 L_xmsu4=1
.param W_xma1=20 L_xma1=1
.param W_xma2=20 L_xma2=1
